import{_ as a,C as r,o as i,c as n,j as o,a as s,E as d,a2 as l}from"./chunks/framework.B5uwLxFG.js";const M=JSON.parse('{"title":"Free Online Video Cropper, Trimmer, and Resizer","description":"Crop, trim, and resize MP4, WebM, MKV, MOV, and AVI videos to a new duration, aspect ratio, or exact resolution. Export privately as WebM, MKV, or MP4.","frontmatter":{"title":"Free Online Video Cropper, Trimmer, and Resizer","description":"Crop, trim, and resize MP4, WebM, MKV, MOV, and AVI videos to a new duration, aspect ratio, or exact resolution. Export privately as WebM, MKV, or MP4.","pageClass":"crop-tool-layout","permalink":"/cropvideo/","canonicalUrl":"https://curvednebula.com/cropvideo/","meta":[{"name":"keywords","content":"crop video online, trim video online, resize video online, MKV video cropper, AVI video cropper, crop AVI video, change video aspect ratio, video resolution converter, WebCodecs video editor, crop video to 9:16, crop video to 16:9"},{"property":"og:title","content":"Free Online Video Cropper, Trimmer, and Resizer"},{"property":"og:description","content":"Crop, trim, and resize MP4, WebM, MKV, MOV, and AVI videos locally, then export as WebM, MKV, or MP4."},{"property":"og:type","content":"website"},{"property":"og:url","content":"https://curvednebula.com/cropvideo/"},{"name":"twitter:card","content":"summary"},{"name":"twitter:title","content":"Free Online Video Cropper, Trimmer, and Resizer"},{"name":"twitter:description","content":"Crop, trim, and resize MP4, WebM, MKV, MOV, and AVI videos locally, then export as WebM, MKV, or MP4."}],"aside":false},"headers":[],"relativePath":"cropvideo/index.md","filePath":"cropvideo/README.md"}'),p={name:"cropvideo/index.md"};function c(h,e,u,m,v,b){const t=r("VideoCrop");return i(),n("div",null,[e[0]||(e[0]=o("h1",{id:"crop-trim-and-resize-videos-online",tabindex:"-1"},[s("Crop, Trim, and Resize Videos Online "),o("a",{class:"header-anchor",href:"#crop-trim-and-resize-videos-online","aria-label":'Permalink to "Crop, Trim, and Resize Videos Online"'},"​")],-1)),d(t),e[1]||(e[1]=l('<h2 id="about" tabindex="-1">About <a class="header-anchor" href="#about" aria-label="Permalink to &quot;About&quot;">​</a></h2><p>Crop a video to a custom area or a common aspect ratio, trim unwanted time from the beginning or end, resize it to an exact output resolution, and save the result as WebM, MKV, or MP4. MP4, WebM, MKV, MOV, and AVI input files are supported. Processing happens locally in your browser — your video is never uploaded.</p><h2 id="how-to-crop-a-video" tabindex="-1">How to crop a video <a class="header-anchor" href="#how-to-crop-a-video" aria-label="Permalink to &quot;How to crop a video&quot;">​</a></h2><ol><li>Select a video from your device or drag and drop it into the cropper.</li><li>Drag inside the crop area to reposition it, then drag the handles to resize it.</li><li>Drag the trim handles to select the part of the video to keep, or set either boundary to the playhead.</li><li>Choose an aspect ratio such as 16:9, 1:1, 4:5, or 9:16.</li><li>Keep the crop resolution, choose a long-edge preset, or enter a custom width and height.</li><li>Select WebM, MKV, or MP4, set a frame rate and quality level, then choose <strong>Save Video</strong>.</li></ol><p>The editor previews only the selected time range with the same crop. Exported dimensions are kept even for broad codec compatibility.</p><p>MP4, MOV, WebM, and MKV input files use a sequential Mediabunny decode pipeline instead of seeking separately for every output frame. AVI and compatibility exports use the same output writers, so every export path supports the selected format.</p><h2 id="browser-compatibility" tabindex="-1">Browser compatibility <a class="header-anchor" href="#browser-compatibility" aria-label="Permalink to &quot;Browser compatibility&quot;">​</a></h2><p>Recent Chromium-based browsers such as Chrome and Edge offer the best compatibility. Video export requires WebCodecs and must run in a secure browser context such as HTTPS.</p><p><strong>Input files supported:</strong> MP4, M4V, MOV, WebM, MKV, and AVI.</p><ul><li><strong>MP4, M4V, and MOV:</strong> Usually offer the broadest input compatibility when they contain H.264 video and AAC audio. Files using HEVC, ProRes, or another codec still depend on the codecs available in the browser and operating system.</li><li><strong>WebM:</strong> Requires browser support for the VP8 or VP9 video codec used by the file. Opus audio also requires a compatible audio decoder.</li><li><strong>MKV and AVI:</strong> Browser-specific. The tool can read these containers, but the video and audio codecs inside them must still be supported by WebCodecs on the current device. Recent Chrome and Edge generally provide the best results.</li><li>Non-AVI files must also be playable by the browser&#39;s built-in video player so the editor can show a preview.</li></ul><p><strong>Output files supported:</strong> WebM, MKV, and MP4.</p><ul><li><strong>WebM and MKV:</strong> Use VP9 or VP8 video and, when available, Opus audio. VP9, VP8, and Opus encoder availability varies by browser and device.</li><li><strong>MP4:</strong> Uses H.264 video and, when available, AAC audio. H.264 encoding can depend on the device&#39;s hardware and operating system. AAC encoding is especially browser-specific and may be unavailable in Firefox or on desktop Linux.</li><li>The tool checks the selected output codecs at runtime. If the video codec is unavailable, export stops with an explanatory message. If only the audio encoder is unavailable, the video is exported without audio and the tool shows a warning.</li><li>Safari added WebCodecs audio encoding and decoding in Safari 26. Earlier Safari versions may open some input videos but cannot preserve their audio during export.</li></ul><h2 id="frequently-asked-questions" tabindex="-1">Frequently asked questions <a class="header-anchor" href="#frequently-asked-questions" aria-label="Permalink to &quot;Frequently asked questions&quot;">​</a></h2><h3 id="can-i-remove-time-from-the-beginning-or-end" tabindex="-1">Can I remove time from the beginning or end? <a class="header-anchor" href="#can-i-remove-time-from-the-beginning-or-end" aria-label="Permalink to &quot;Can I remove time from the beginning or end?&quot;">​</a></h3><p>Yes. Move the start and end trim handles, enter exact timestamps, or move the playhead and choose <strong>Set to playhead</strong>. Preview playback stays inside the selected range, and the exported video starts at time zero.</p><h3 id="can-i-crop-a-landscape-video-into-a-vertical-video" tabindex="-1">Can I crop a landscape video into a vertical video? <a class="header-anchor" href="#can-i-crop-a-landscape-video-into-a-vertical-video" aria-label="Permalink to &quot;Can I crop a landscape video into a vertical video?&quot;">​</a></h3><p>Yes. Choose <strong>Vertical · 9:16</strong>, move the selection over the important part of the frame, and select a suitable output resolution such as a 1080-pixel long edge.</p><h3 id="can-i-enter-an-exact-video-resolution" tabindex="-1">Can I enter an exact video resolution? <a class="header-anchor" href="#can-i-enter-an-exact-video-resolution" aria-label="Permalink to &quot;Can I enter an exact video resolution?&quot;">​</a></h3><p>Yes. Choose <strong>Custom</strong> under Output resolution, then enter the width and height. Keep the aspect ratio option enabled to avoid stretching.</p>',19))])}const V=a(p,[["render",c]]);export{M as __pageData,V as default};
